import XCTest
@testable import HandyTools

/// Kindle books with dictionary compression open (File Opener tier 2). The tables below are made up and tiny: a HUFF
/// record, one CDIC dictionary (one phrase is itself compressed), and a compressed text — checked off-device against
/// a port of the same decoder.
final class MobiHuffTests: XCTestCase {
    private let huff = [UInt8](Data(base64Encoded: "")!)
    private let cdic = [UInt8](Data(base64Encoded: "")!)
    private let text = [UInt8](Data(base64Encoded: "AAECAwQFFA==")!)

    func testDictionaryCompressedTextUnpacks() throws {
        let h = try XCTUnwrap(MobiHuff(huff: huff, cdics: [cdic]))
        XCTAssertEqual(String(decoding: h.unpack(text), as: UTF8.self), "The quick brown fox jumps over the lazy dog. ")
        // Unpacking again reuses the phrase that was decompressed the first time.
        XCTAssertEqual(String(decoding: h.unpack(text), as: UTF8.self), "The quick brown fox jumps over the lazy dog. ")
    }

    func testDamagedTablesAreRefused() {
        XCTAssertNil(MobiHuff(huff: Array(huff.prefix(20)), cdics: [cdic]))
        XCTAssertNil(MobiHuff(huff: huff, cdics: [Array("CDIC".utf8)]))
    }
}
